"use strict";
const test=require("node:test"),assert=require("node:assert/strict"),fs=require("node:fs"),path=require("node:path");
const {fixture}=require("./helper"),{create}=require("../plugin/service");
test("Brain owns encrypted memories, goals, sources and awareness without other feature data",async t=>{const f=fixture(t,"kai.brain"),app=create(f.api);t.after(()=>app.dispose());const note=await app.call("brain.ui.note",{title:"Memory",text:"private-memory-example"});await app.call("brain.ui.goal",{title:"Build something",detail:"A goal"});const state=await app.call("brain.ui.status");assert.equal(state.notes[0].id,note.id);assert.equal(state.goals.length,1);assert.ok(state.brain.awareness);const envelope=JSON.parse(fs.readFileSync(path.join(f.root,"state.json")));const disk=JSON.parse(f.api.secrets.decryptString(Buffer.from(envelope.encrypted,"base64")));assert.ok(!Object.hasOwn(disk,"connections"));assert.ok(!Object.hasOwn(disk,"workflows"));assert.ok(!Object.hasOwn(disk,"composio"));assert.doesNotMatch(fs.readFileSync(path.join(f.root,"state.json"),"utf8"),/private-memory-example/);await app.dispose();const reopened=create(f.api);assert.equal((await reopened.call("brain.ui.status")).notes[0].text,"private-memory-example");await reopened.dispose();});
test("provider-side reviews gate memory writes and corrupted state is not replaced",async t=>{const f=fixture(t,"kai.brain"),app=create(f.api);t.after(()=>app.dispose());const spec=f.provided.get("kai.brain");await spec.call("remember",{title:"Reviewed",text:"Approved memory"},{signal:f.api.signal});assert.equal(f.confirmations.length,1);f.api.desktop.confirm=async()=>false;await assert.rejects(spec.call("remember",{title:"Denied",text:"Do not save"}),/not saved/);assert.equal((await app.call("brain.ui.status")).notes.length,1);await app.dispose();fs.writeFileSync(path.join(f.root,"state.json"),"broken");const bad=create(f.api);assert.equal((await bad.call("brain.ui.status")).locked,true);await assert.rejects(bad.call("brain.ui.note",{text:"lost"}),/preserved/);assert.equal(fs.readFileSync(path.join(f.root,"state.json"),"utf8"),"broken");await bad.dispose();});
test("missing Connections fails clearly without creating a fake source",async t=>{const f=fixture(t,"kai.brain"),app=create(f.api);t.after(()=>app.dispose());await assert.rejects(app.call("brain.ui.source",{connectionId:"missing",operationId:"read",name:"No source"}),/unavailable/);assert.equal((await app.call("brain.ui.status")).sources.length,0);});
test("plugin-owned navigation uses generic public desktop services",async t=>{const f=fixture(t,"kai.brain"),opened=[];f.api.desktop.openPlugin=async(...v)=>opened.push(v);f.api.desktop.openCore=async(...v)=>opened.push(v);const app=create(f.api);t.after(()=>app.dispose());await app.call("desktop.openView",{view:"workflows"});await app.call("desktop.openView",{view:"settings",section:"website-account"});assert.deepEqual(opened,[["kai.workflows",undefined],["settings","website-account"]]);await assert.rejects(app.call("desktop.openView",{view:"unknown"}),/Unknown/);});
test("chat-source selection grants the union of selected IDs before background reads",async t=>{const f=fixture(t,"kai.brain"),grants=[];let allowed=[];f.provided.set("kai.assistant",{methods:["chats.list","chats.get","chats.grant","chats.restrict"],call:async(method,input)=>{if(method==="chats.list")return{chats:[{id:"one",title:"One"},{id:"two",title:"Two"}]};if(method==="chats.grant"){allowed=input.ids;grants.push([...allowed]);return{ids:allowed};}if(method==="chats.restrict"){allowed=allowed.filter(id=>input.ids.includes(id));return{ids:allowed};}assert.ok(allowed.includes(input.id));return{id:input.id,title:input.id,messages:[{role:"user",content:"Private selected conversation"}]};}});const app=create(f.api);t.after(()=>app.dispose());const one=await app.call("brain.ui.brainSource",{kind:"chats",name:"First",chatIds:["one"],autoSync:true});await app.call("brain.ui.brainSource",{kind:"chats",name:"Second",chatIds:["two"],autoSync:true});assert.deepEqual(grants,[["one"],["one","two"]]);await app.call("brain.ui.sync",{id:one.id});assert.match(JSON.stringify((await app.call("brain.ui.status")).notes),/Private selected conversation/);await app.call("brain.ui.remove",{kind:"sources",id:one.id});assert.deepEqual(allowed,["two"]);});
